using System;
using System.Text;
using System.Text.RegularExpressions;

public static class StringExtensions
{
    public static string ToSnakeCase(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return name;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int length = name.Length;

        while (i < length)
        {
            char current = name[i];

            // If it's the start of a new word (Uppercase) and not the first character
            if (i > 0 && char.IsUpper(current))
            {
                // Check if we need an underscore:
                // 1. Current is Upper and previous was Lower (e.g., aB -> a_b)
                // 2. Current is Upper, previous was Upper, but next is Lower (e.g., HTTPR -> http_r)
                //    This handles the "XMLParser" -> "xml_parser" case.
                bool prevIsLower = char.IsLower(name[i - 1]);
                bool nextIsLower = (i + 1 < length && char.IsLower(name[i + 1]));

                if (prevIsLower || nextIsLower)
                {
                    result.Append('_');
                }
            }

            result.Append(char.ToLower(current));
            i++;
        }

        return result.ToString();
    }
}
