        return 0
    }

    $count = 0
    $currentDate = $Start.Date

    while ($currentDate -le $End.Date) {
        $dayOfWeek = $currentDate.DayOfWeek
        if ($dayOfWeek -ne 'Saturday' -and $dayOfWeek -ne 'Sunday') {
            $count++
        }
        $currentDate = $currentDate.AddDays(1)
    }

    return $count
}
