function Format-Bytes {
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [long]$Bytes
    )

    if ($Bytes -lt 1024) {
        return "{0} B" -f $Bytes
    }

    $units = @('KB', 'MB', 'GB', 'TB', 'PB')
    $exponent = [Math]::Floor([Math]::Log($Bytes, 1024))

    # Clamp exponent to the maximum available unit index
    if ($exponent -gt $units.Count) {
        $exponent = $units.Count
    }

    $value = $Bytes / [Math]::Pow(1024, $exponent)

    # Using InvariantCulture via GetString for the dot decimal separator
    return $value.ToString("F1", [System.Globalization.CultureInfo]::InvariantCulture) + " " + $units[$exponent - 1]
}
